from PIL import Image
import numpy as np
im=np.array(Image.open('/tmp/offset_practice.png').convert('RGB'));g=im.mean(2)
# for each y-position line, find dark x and y profiles
m=g<100
# identify four boxes by components
from scipy import ndimage
lab,n=ndimage.label(m,np.ones((3,3)))
for i,s in enumerate(ndimage.find_objects(lab),1):
 if s:
  yy,xx=np.where(lab[s]==i); x0=s[1].start;y0=s[0].start; xx=xx+x0;yy=yy+y0
  if len(xx)>100:
   print('comp',len(xx),'box',xx.min(),yy.min(),xx.max(),yy.max(),'cent',xx.mean(),yy.mean())
   # median cross-section thickness along principal axis according to thin horizontal/vertical orientation
   if xx.ptp()>yy.ptp():
    widths=[]
    for x in range(xx.min()+30,xx.max()-30):
     ys=np.where(m[:,x])[0]
     ys=ys[(ys>=yy.min())&(ys<=yy.max())]
     if len(ys): widths.append(len(ys))
    print('  horizontal med/max width',np.median(widths),max(widths))
   else:
    widths=[]
    for y in range(yy.min()+30,yy.max()-30):
     xs=np.where(m[y,:])[0];xs=xs[(xs>=xx.min())&(xs<=xx.max())]
     if len(xs):widths.append(len(xs))
    print('  vertical med/max width',np.median(widths),max(widths))
